mapper.select:
SELECT skuId, supplierId, supplierName, lastPrice, lastPoNo, lastPoAt FROM ( SELECT i.sku_id AS skuId, po.supplier_id AS supplierId, s.name AS supplierName, i.purchase_price AS lastPrice, po.po_no AS lastPoNo, po.created_at AS lastPoAt, ROW_NUMBER() OVER (PARTITION BY i.sku_id ORDER BY po.created_at DESC, i.id DESC) AS rn FROM purchase_order_item i JOIN purchase_order po ON po.id = i.po_id JOIN supplier s ON s.id = po.supplier_id WHERE po.status != 'DRAFT' AND i.sku_id IN
#{skuId}
) t WHERE rn = 1
